def carry_over(apps, schema_editor):
    """A pass stage 2 already stored on a booking becomes its first
    BoardingPass row, the passenger named from the barcode."""
    from travel.barcodes import bcbp
    Booking = apps.get_model('travel', 'Booking')
    BoardingPass = apps.get_model('travel', 'BoardingPass')
    for b in Booking.objects.exclude(pass_code=''):
        info = bcbp(b.pass_code)
        BoardingPass.objects.create(
            booking=b, name=(info.get('name') or '')[:80], code=b.pass_code,
            format=b.pass_format or 'aztec', seat=(info.get('seat') or '')[:8],
            wallet_link=b.wallet_link or '')


